export type RoleKey = (typeof ROLE_TEMPLATES)[number]['key'];

/** Expands a template's grants into concrete permission keys with their scope. */
export function resolveRoleGrants(template: RoleTemplate): Map<PermissionKey, DataScope> {
  const result = new Map<PermissionKey, DataScope>();
  for (const grant of template.grants) {
    for (const permission of PERMISSIONS) {
      const allowed = grant.allow.some((p) => matchesPermission(p, permission.key));
      const excluded = (grant.except ?? []).some((p) => matchesPermission(p, permission.key));
      if (allowed && !excluded) {
        result.set(permission.key, grant.scope);
      }
    }
  }
  return result;
}
